+      localDocsDopplerArguments,
+      {
+        env: filterLocalDopplerEnvironment(environment),
+        extendEnv: false,
+        forceKillAfter: "2 seconds",
+        stderr: "inherit",
+        stdin: "inherit",
+        stdout: "inherit",
+      }
